int parse_network_packet(char* packet_data, int packet_len, char* output_buffer, int buffer_size) {
    // 检查输入参数的有效性
    if (packet_data == NULL || output_buffer == NULL || packet_len <= 0 || buffer_size <= 0) {
        return -1; // 参数无效
    }

    // 假设数据包格式为：[长度字段(4字节)][字符串数据]
    if (packet_len < 4) {
        return -2; // 数据包太短，无法包含长度字段
    }

    // 从数据包中读取字符串长度（假设为网络字节序的32位整数）
    uint32_t string_len;
    memcpy(&string_len, packet_data, sizeof(uint32_t));

    // 转换为本地字节序（如果需要）
    // 注意：在实际网络编程中，可能需要使用ntohl()进行字节序转换
    // string_len = ntohl(string_len);

    // 检查数据包长度是否足够包含声明的字符串长度
    if (packet_len < 4 + string_len) {
        return -3; // 数据包长度不足
    }

    // 检查输出缓冲区是否足够大
    if (string_len >= buffer_size) {
        return -4; // 输出缓冲区太小
    }

    // 将字符串数据复制到输出缓冲区
    memcpy(output_buffer, packet_data + 4, string_len);

    // 确保输出缓冲区以null结尾
    output_buffer[string_len] = '\0';

    return string_len; // 返回复制的字符串长度
}
